zi_rekap_maskapai:
@EndUserText.label: 'Rekap penumpang per maskapai'
define view entity ZI_Rekap_Maskapai
  as select from ZI_Penerbangan
{
  key NamaMaskapai,
      count(*)    as Penerbangan,
      sum(Terisi) as Penumpang
}
group by NamaMaskapai

zr_penerbangan.bdef:
managed implementation in class zbp_r_penerbangan unique;
strict ( 2 );

define behavior for ZR_Penerbangan alias Penerbangan
persistent table zflight
lock master
authorization master ( instance )
{
  create;
  update;
  delete;

  field ( readonly : update ) Maskapai, Nomor, Tanggal;
  field ( mandatory ) Ke;

  determination isiKapasitas on modify { create; }
  validation cekKursi on save { create; update; field Terisi, Kapasitas; }
  action tandaiPenuh result [1] $self;
}

za_diskon:
@EndUserText.label: 'Parameter action diskon'
define abstract entity ZA_Diskon
{
  persen : abap.int4;
}

zr_travel.bdef:
managed implementation in class zbp_r_travel unique;
strict ( 2 );

define behavior for ZR_Travel alias Travel
persistent table ztravel
lock master
{
  create;
  update;
  delete ( features : instance );
  field ( readonly ) Status;
  association _Booking { create; }
  action ( features : instance ) diskon parameter ZA_Diskon result [1] $self;
}

define behavior for ZR_Booking alias Booking
persistent table zbooking
lock dependent by _Travel
{
  update;
  delete;
  field ( readonly ) TravelID;
  association _Travel;
}
